(async()=>{const out={};for(const value of [0,.5,2]){const c=new OfflineAudioContext(1,512,8000),b=c.createBuffer(1,1024,8000),s=c.createBufferSource();b.getChannelData(0).fill(1);s.buffer=b;s.connect(c.destination);s.playbackRate.setValueAtTime(value,128/8000);let ended=false;s.onended=()=>{ended=true};s.start(0,0,256/8000);const result=Array.from((await c.startRendering()).getChannelData(0));await new Promise(r=>setTimeout(r,10));out[value]=[result.filter(v=>v!==0).length,ended]}return out})()
